import React, { useRef, useState, useEffect } from "react";

const ConceptBoard = () => {
  const boardRef = useRef(null);
  const fileInputRef = useRef(null);

  const [images, setImages] = useState([]);
  const [draggingId, setDraggingId] = useState(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [transform, setTransform] = useState({ scale: 1, x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  const [showModal, setShowModal] = useState(false);
  const [pendingImage, setPendingImage] = useState(null);
  const [inputName, setInputName] = useState("");
  const [inputCategory, setInputCategory] = useState("");

  const [isFullscreen, setIsFullscreen] = useState(false);
  const [errorMessage, setErrorMessage] = useState(null);

  // Safely save to localStorage with error handling
  const safelyStoreImages = (imagesToStore) => {
    try {
      // Only store essential data, not the full image data
      const lightweightImages = imagesToStore.map(img => ({
        id: img.id,
        x: img.x,
        y: img.y,
        name: img.name,
        category: img.category,
        width: img.width,
        height: img.height,
        // We don't store the src (image data) to avoid exceeding quota
      }));
      
      localStorage.setItem('melodicJustice_conceptImagePositions', JSON.stringify(lightweightImages));
      return true;
    } catch (error) {
      console.error('Failed to save to localStorage:', error);
      setErrorMessage("Warning: Cannot save image positions to localStorage. Your changes won't persist after reload.");
      return false;
    }
  };

  // Handle mouse events for dragging images
  const handleMouseDown = (e, id) => {
    e.stopPropagation();
    const image = images.find((img) => img.id === id);
    setDraggingId(id);
    setDragOffset({ x: e.clientX - image.x, y: e.clientY - image.y });
  };

  const handleMouseMove = (e) => {
    if (draggingId) {
      setImages((prev) => {
        const newImages = prev.map((img) =>
          img.id === draggingId
            ? { ...img, x: e.clientX - dragOffset.x, y: e.clientY - dragOffset.y }
            : img
        );
        
        // Try to store positions, but don't worry if it fails
        safelyStoreImages(newImages);
        
        return newImages;
      });
    } else if (isPanning) {
      setTransform((prev) => ({
        ...prev,
        x: prev.x + (e.clientX - panStart.x),
        y: prev.y + (e.clientY - panStart.y),
      }));
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseUp = () => {
    setDraggingId(null);
    setIsPanning(false);
  };

  // Handle wheel events for zooming
  const handleWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY * -0.001;
    setTransform((prev) => ({
      ...prev,
      scale: Math.min(3, Math.max(0.2, prev.scale + delta)),
    }));
  };

  const handleBackgroundMouseDown = (e) => {
    if (e.button === 0) {
      setIsPanning(true);
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  // Handle image upload - now with image size limitations
  const handleAddImageClick = () => {
    fileInputRef.current.click();
  };

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    // Check file size - limit to 1MB to be safe
    if (file.size > 1024 * 1024) {
      setErrorMessage("Image too large. Please select an image smaller than 1MB.");
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      // Create an image element to get the natural dimensions
      const img = new Image();
      img.onload = () => {
        // Calculate dimensions to maintain aspect ratio
        const maxWidth = 250; // Set maximum thumbnail width
        const aspectRatio = img.naturalWidth / img.naturalHeight;
        const width = maxWidth;
        const height = width / aspectRatio;

        setPendingImage({
          src: reader.result,
          width: width,
          height: height,
          aspectRatio: aspectRatio,
          originalWidth: img.naturalWidth,
          originalHeight: img.naturalHeight
        });
        setInputName(file.name.split('.')[0] || "Untitled"); // Use filename as default name
        setShowModal(true);
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
    e.target.value = null; // Reset input so same file can be selected again
  };

  const handleAddImageFromModal = () => {
    if (!pendingImage) return;
    
    // Generate a unique ID based on timestamp
    const newId = Date.now().toString();
    
    // Create the new image object
    const newImage = {
      id: newId,
      src: pendingImage.src,
      x: 100,
      y: 100,
      name: inputName || "Untitled",
      category: inputCategory || "Uncategorized",
      width: pendingImage.width,
      height: pendingImage.height,
      aspectRatio: pendingImage.aspectRatio,
      originalWidth: pendingImage.originalWidth,
      originalHeight: pendingImage.originalHeight
    };

    // Add the image to state
    const updatedImages = [...images, newImage];
    setImages(updatedImages);
    
    // Try to save position data only (not the actual image data)
    safelyStoreImages(updatedImages);
    
    // Close the modal and reset form
    setShowModal(false);
    setInputName("");
    setInputCategory("");
    setPendingImage(null);
  };

  // Handle fullscreen toggle
  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      boardRef.current.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable fullscreen: ${err.message}`);
      });
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  // Delete an image
  const handleDeleteImage = (id) => {
    const updatedImages = images.filter(img => img.id !== id);
    setImages(updatedImages);
    safelyStoreImages(updatedImages);
  };

  // Set up event listeners
  useEffect(() => {
    const board = boardRef.current;
    if (board) {
      board.addEventListener("wheel", handleWheel, { passive: false });
      return () => board.removeEventListener("wheel", handleWheel);
    }
  }, []);

  // Handle fullscreen change event
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  // Close error message after timeout
  useEffect(() => {
    if (errorMessage) {
      const timer = setTimeout(() => {
        setErrorMessage(null);
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [errorMessage]);

  return (
    <div className="rounded-lg p-4" style={{ backgroundColor: '#1a1a1a' }}>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Concept Board</h2>
          <p className="text-gray-400">Organize and manage concept art and reference images</p>
        </div>
        
        <div className="flex gap-2">
          <button
            onClick={handleAddImageClick}
            className="px-4 py-2 rounded-lg flex items-center gap-2 bg-teal-500 text-white hover:bg-teal-600 transition-all"
          >
            <span>+ Add Image</span>
          </button>
          
          <button
            onClick={toggleFullscreen}
            className="p-2 rounded-lg bg-gray-700 text-white hover:bg-gray-600 transition-all"
          >
            {isFullscreen ? "Exit Fullscreen" : "Fullscreen"}
          </button>
        </div>
      </div>
      
      {/* Error message */}
      {errorMessage && (
        <div 
          style={{ 
            backgroundColor: '#f44336', 
            color: 'white', 
            padding: '10px', 
            borderRadius: '4px',
            marginBottom: '10px'
          }}
        >
          {errorMessage}
          <button 
            onClick={() => setErrorMessage(null)} 
            style={{ 
              marginLeft: '10px', 
              background: 'rgba(255,255,255,0.2)', 
              border: 'none', 
              borderRadius: '50%', 
              width: '20px', 
              height: '20px',
              cursor: 'pointer',
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              lineHeight: 1
            }}
          >×</button>
        </div>
      )}
      
      <div
        ref={boardRef}
        onMouseDown={handleBackgroundMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        style={{
          position: "relative",
          width: "100%",
          height: "calc(100vh - 200px)",
          backgroundColor: "#1a1a1a",
          overflow: "hidden",
          cursor: isPanning ? "grabbing" : "grab",
        }}
      >
        {/* Concept Images */}
        <div
          style={{
            transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`,
            transformOrigin: "0 0",
            position: "absolute",
            top: 0,
            left: 0,
          }}
        >
          {images.map((img) => (
            <div
              key={img.id}
              style={{
                position: "absolute",
                left: img.x,
                top: img.y,
                width: img.width,
                cursor: "move",
                userSelect: "none",
                background: "#2a2a2a",
                borderRadius: "8px",
                padding: "4px",
                boxShadow: "0 4px 16px rgba(0,0,0,0.4)",
              }}
              onMouseDown={(e) => handleMouseDown(e, img.id)}
            >
              <div className="flex justify-end mb-1">
                <button 
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDeleteImage(img.id);
                  }}
                  style={{
                    backgroundColor: '#f44336',
                    color: 'white',
                    width: '20px',
                    height: '20px',
                    borderRadius: '50%',
                    border: 'none',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '12px'
                  }}
                >×</button>
              </div>
              <img
                src={img.src}
                alt={img.name}
                style={{
                  width: "100%",
                  height: "auto", // This ensures aspect ratio is preserved
                  borderRadius: "4px",
                  pointerEvents: "none",
                  maxHeight: "400px", // Limit maximum height
                }}
                draggable={false}
              />
              <div style={{ color: "#fff", fontSize: "0.8rem", marginTop: "4px", textAlign: "center" }}>
                <strong>{img.name}</strong>
                {img.category && (
                  <div style={{ fontSize: "0.7rem", opacity: 0.7 }}>{img.category}</div>
                )}
              </div>
            </div>
          ))}
        </div>

        {/* Empty state */}
        {images.length === 0 && (
          <div style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            textAlign: 'center',
            color: '#777'
          }}>
            <p style={{ marginBottom: '10px' }}>No concept images added yet</p>
            <button 
              onClick={handleAddImageClick}
              style={{
                padding: '8px 16px',
                backgroundColor: '#00d1b2',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer'
              }}
            >
              Add Your First Image
            </button>
          </div>
        )}

        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleImageUpload}
          style={{ display: "none" }}
        />
      </div>

      {/* Modal */}
      {showModal && (
        <div
          style={{
            position: "fixed",
            top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: "rgba(0,0,0,0.7)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 1000,
          }}
        >
          <div style={{
            background: "#222",
            padding: "20px",
            borderRadius: "8px",
            width: "300px",
            maxWidth: "90%",
          }}>
            <h3 style={{ color: "#fff", marginBottom: "15px" }}>Add Image Details</h3>
            
            {/* Preview */}
            {pendingImage && (
              <div style={{ marginBottom: "15px" }}>
                <img 
                  src={pendingImage.src} 
                  alt="Preview" 
                  style={{ 
                    width: "100%", 
                    height: "auto",
                    maxHeight: "200px", 
                    objectFit: "contain",
                    background: "#1a1a1a",
                    borderRadius: "4px"
                  }} 
                />
                <div style={{ color: "#aaa", fontSize: "0.8rem", marginTop: "4px" }}>
                  Original size: {pendingImage.originalWidth} × {pendingImage.originalHeight}
                </div>
              </div>
            )}
            
            <div style={{ marginBottom: "10px" }}>
              <label style={{ color: "#aaa", fontSize: "0.8rem", display: "block", marginBottom: "4px" }}>Image Name</label>
              <input
                type="text"
                placeholder="Name"
                value={inputName}
                onChange={(e) => setInputName(e.target.value)}
                style={{ 
                  padding: "8px", 
                  borderRadius: "4px",
                  width: "100%",
                  backgroundColor: "#333",
                  border: "none",
                  color: "white"
                }}
              />
            </div>
            
            <div style={{ marginBottom: "15px" }}>
              <label style={{ color: "#aaa", fontSize: "0.8rem", display: "block", marginBottom: "4px" }}>Category</label>
              <input
                type="text"
                placeholder="Category (e.g., Character, Environment)"
                value={inputCategory}
                onChange={(e) => setInputCategory(e.target.value)}
                style={{ 
                  padding: "8px", 
                  borderRadius: "4px",
                  width: "100%",
                  backgroundColor: "#333",
                  border: "none",
                  color: "white"
                }}
              />
            </div>
            
            <div style={{ display: "flex", justifyContent: "space-between", marginTop: "10px" }}>
              <button 
                onClick={() => setShowModal(false)} 
                style={{ 
                  padding: "8px 12px", 
                  background: "#444", 
                  color: "#fff", 
                  border: "none", 
                  borderRadius: "4px",
                  cursor: "pointer"
                }}
              >
                Cancel
              </button>
              <button 
                onClick={handleAddImageFromModal} 
                style={{ 
                  padding: "8px 16px", 
                  background: "#00d1b2", 
                  color: "#fff", 
                  border: "none", 
                  borderRadius: "4px",
                  cursor: "pointer"
                }}
              >
                Add Image
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ConceptBoard;
